library(testthat)

reverse_str <- function(s) {
  paste(rev(strsplit(s, "")[[1]]), collapse = "")
}

test_that("reverse_str reverses a string", {
  expect_equal(reverse_str("hello"), "olleh")
  expect_equal(reverse_str(""), "")
})
#> Test passed

